import React from 'react';
import './Experience.css';

function Experience() {
  const experiences = [
    {
      role: 'Project Coordinator',
      organization: 'Your Current Organization',
      period: '2023 - Present',
      achievements: [
        'Coordinate cross-functional teams across multiple departments',
        'Manage project timelines and deliverables',
        'Facilitate stakeholder communication and reporting'
      ]
    },
    {
      role: 'AI Workshop Coordinator',
      organization: 'University Program',
      period: '2023',
      achievements: [
        'Organized and led AI Vibe Coding Workshop for 50+ participants',
        'Developed curriculum and hands-on learning materials',
        'Managed event logistics and participant engagement'
      ]
    },
    {
      role: 'Student Leadership Role',
      organization: 'University',
      period: '2022 - 2023',
      achievements: [
        'Led team initiatives and collaborative projects',
        'Coordinated events and programs',
        'Mentored peers in professional development'
      ]
    }
  ];

  return (
    <section id="experience" className="experience">
      <h2>Professional Timeline</h2>

      <div className="timeline">
        {experiences.map((exp, index) => (
          <div key={index} className="timeline-item">
            <div className="timeline-marker"></div>
            <div className="timeline-content">
              <div className="timeline-header">
                <h3>{exp.role}</h3>
                <span className="timeline-period">{exp.period}</span>
              </div>
              <p className="timeline-org">{exp.organization}</p>
              <ul className="timeline-achievements">
                {exp.achievements.map((achievement, idx) => (
                  <li key={idx}>{achievement}</li>
                ))}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Experience;
